script:
(function () {
  'use strict';
  // Rent vs. buy: month-by-month comparison of net worth over the chosen horizon.
  //   Mortgage payment M = L x i / (1 - (1 + i)^-n), i = rate / 12 (M = L / n at 0%).
  //   Owning each month: principal & interest + property tax and maintenance (% of the home's value
  //   that year) + insurance and HOA (growing with inflation) + PMI while the balance is above 80%
  //   of the price. Renting: rent (growing yearly) + renter's insurance.
  //   The renter invests the down payment and buying closing costs up front; each month whoever has
  //   the lower housing cost invests the difference at the assumed return (monthly (1 + r)^(1/12) - 1).
  //   Buyer net worth = home value x (1 - selling costs) - loan balance + buyer's investments.
  //   Renter net worth = renter's investments. Taxes on investment gains and any mortgage-interest
  //   deduction are ignored.
  // Verified (Node, scratch tests): $320,000 at 6.5% for 30 years -> $2,022.62/month;
  //   $100,000 at 0% for 10 years -> $833.33. With 0% return, 0% growth, 0% rate and no other costs,
  //   buyer and renter net worth reconcile by hand (equity + cash difference). Defaults: $400,000
  //   home, 20% down, 6.5%, 30 years vs $2,200 rent -> see the worked example in the page copy.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var cents = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2, minimumFractionDigits: 2 });

  function num(id) {
    var el = document.getElementById(id);
    if (!el) return NaN;
    var v = parseFloat(el.value);
    return isNaN(v) ? NaN : v;
  }

  function payment(loan, annualRate, years) {
    var n = years * 12, i = annualRate / 12;
    if (loan <= 0 || n <= 0) return 0;
    if (i === 0) return loan / n;
    return loan * i / (1 - Math.pow(1 + i, -n));
  }

  function simulate(o) {
    var loan = o.price * (1 - o.downPct / 100);
    var pmt = payment(loan, o.rate / 100, o.term);
    var i = o.rate / 100 / 12, n = o.term * 12;
    var g = Math.pow(1 + o.ret / 100, 1 / 12) - 1;
    var upfront = o.price * o.downPct / 100 + o.price * o.buyClose / 100;
    var balance = loan, buyInv = 0, rentInv = upfront, buyPaid = upfront, rentPaid = 0;
    var rows = [], firstOwn = 0, firstRent = 0;
    for (var m = 1; m <= o.years * 12; m++) {
      var y = Math.floor((m - 1) / 12);
      var value = o.price * Math.pow(1 + o.apprec / 100, y);
      var infl = Math.pow(1 + o.infl / 100, y);
      var pi = 0;
      if (m <= n && balance > 0) {
        var interest = balance * i;
        pi = Math.min(pmt, balance + interest);
        balance = Math.max(0, balance - (pi - interest));
      }
      var pmi = (o.downPct < 20 && balance > 0.8 * o.price) ? loan * o.pmi / 100 / 12 : 0;
      var own = pi + value * o.propTax / 100 / 12 + value * o.maint / 100 / 12 + o.ins * infl / 12 + o.hoa * infl + pmi;
      var rent = o.rent * Math.pow(1 + o.rentInc / 100, y) + o.rentIns * infl;
      if (m === 1) { firstOwn = own; firstRent = rent; }
      buyInv *= 1 + g; rentInv *= 1 + g;
      if (own > rent) rentInv += own - rent; else buyInv += rent - own;
      buyPaid += own; rentPaid += rent;
      if (m % 12 === 0) {
        var endValue = o.price * Math.pow(1 + o.apprec / 100, m / 12);
        var buyNW = endValue * (1 - o.sellCost / 100) - balance + buyInv;
        rows.push({ year: m / 12, buyPaid: buyPaid, rentPaid: rentPaid, equity: endValue - balance,
                    buyNW: buyNW, rentNW: rentInv });
      }
    }
    return { loan: loan, pmt: pmt, upfront: upfront, firstOwn: firstOwn, firstRent: firstRent, rows: rows };
  }

  function setText(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }

  function update() {
    var o = {
      price: num('rbPrice'), downPct: num('rbDown'), rate: num('rbRate'), term: parseInt(document.getElementById('rbTerm').value, 10),
      buyClose: num('rbBuyClose'), propTax: num('rbPropTax'), ins: num('rbIns'), hoa: num('rbHoa'), maint: num('rbMaint'),
      apprec: num('rbApprec'), sellCost: num('rbSellCost'), rent: num('rbRent'), rentInc: num('rbRentInc'),
      rentIns: num('rbRentIns'), years: Math.round(num('rbYears')), ret: num('rbReturn'), infl: num('rbInfl'), pmi: num('rbPmi')
    };
    if (!(o.term > 0)) o.term = 30;
    var error = document.getElementById('rbError');
    var vals = Object.keys(o).map(function (k) { return o[k]; });
    var bad = vals.some(function (v) { return !isFinite(v); }) ||
              o.price <= 0 || o.price > 1e9 || o.downPct < 0 || o.downPct > 100 || o.rate < 0 || o.rate > 30 ||
              o.buyClose < 0 || o.buyClose > 20 || o.propTax < 0 || o.propTax > 10 || o.ins < 0 || o.hoa < 0 ||
              o.maint < 0 || o.maint > 10 || o.apprec < -20 || o.apprec > 20 || o.sellCost < 0 || o.sellCost > 20 ||
              o.rent < 0 || o.rentInc < -20 || o.rentInc > 20 || o.rentIns < 0 || o.years < 1 || o.years > 40 ||
              o.ret < -20 || o.ret > 30 || o.infl < -10 || o.infl > 20 || o.pmi < 0 || o.pmi > 5;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a home price above $0, a down payment from 0 to 100%, non-negative costs, ' +
                          'growth rates from -20% to 20% and a comparison period of 1 to 40 years.';
      return;
    }
    var r = simulate(o), last = r.rows[r.rows.length - 1];
    var diff = last.buyNW - last.rentNW;
    var breakEven = null;
    for (var k = 0; k < r.rows.length; k++) { if (r.rows[k].buyNW >= r.rows[k].rentNW - 0.5) { breakEven = r.rows[k].year; break; } }

    var even = Math.abs(diff) < 1;
    var signed = function (v) { return Math.round(v) < 0 ? '\u2212' + money.format(-v) : money.format(Math.abs(v) < 0.5 ? 0 : v); };
    setText('rbVerdict', even ? 'About even' : diff > 0 ? 'Buying' : 'Renting');
    setText('rbVerdictBy', money.format(Math.abs(diff)));
    setText('rbBreakEven', breakEven === null ? 'Not within ' + o.years + (o.years === 1 ? ' year' : ' years') :
            'Year ' + breakEven);
    setText('rbPmt', cents.format(r.pmt));
    setText('rbOwnMonthly', cents.format(r.firstOwn));
    setText('rbRentMonthly', cents.format(r.firstRent));
    setText('rbUpfront', money.format(r.upfront));
    setText('rbBuyNW', signed(last.buyNW));
    setText('rbRentNW', signed(last.rentNW));
    var span = o.years + (o.years === 1 ? ' year' : ' years');
    setText('rbSummary', even ? 'Buying and renting leave you with about the same net worth after ' + span + '.' :
            (diff > 0 ? 'Buying' : 'Renting') + ' leaves you about ' + money.format(Math.abs(diff)) +
            ' better off after ' + span + ', assuming you sell the home at the end.');

    document.getElementById('rbTable').innerHTML = r.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money.format(row.buyPaid) + '</td><td>' + money.format(row.rentPaid) +
             '</td><td>' + money.format(row.equity) + '</td><td>' + signed(row.buyNW) + '</td><td>' + signed(row.rentNW) +
             '</td><td>' + signed(row.buyNW - row.rentNW) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('rbForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
